import {
  Bs2DSRowDirective,
  Bs2DSOrderDirective,
  Bs2DSPushDirective,
  Bs2DSOffsetDirective,
  Bs2DSColumnDirective,
} from '@bs2/design-system/directives/bs2-ds-grid';
import { moduleMetadata, type Meta, type StoryObj } from '@storybook/angular';
import { Component } from '@angular/core';

const boxStyle = `
      <style>
        .box {
          font-size:12px;
          display: block;
          text-align: center;
          width:100%;
          border-radius: 5px;
          padding: 5px 0px;
          background-color: rgba(0,0,0,0.1);
          margin-bottom: 10px;
        }
      </style>
      `;

const column = (amount: number, columns?: number[], offsets?: number[], pushs?: number[], orders?: number[]) =>
  Array(amount)
    .fill(0)
    .map(
      () =>
        `<div
            ${(columns || []).length > 0 ? `[bs2-ds-column]="${JSON.stringify(columns || [])}"` : ''}
            ${(offsets || []).length > 0 ? `[bs2-ds-offset]="${JSON.stringify(offsets || [])}"` : ''}
            ${(pushs || []).length > 0 ? `[bs2-ds-push]="${JSON.stringify(pushs || [])}"` : ''}
            ${(orders || []).length > 0 ? `[bs2-ds-order]="${JSON.stringify(orders || [])}"` : ''}
          >
            <span class='box'>
              ${(columns || []).length > 0 ? `columns: ${getBreakpoints(columns)}` : ''}
              ${(offsets || []).length > 0 ? `offsets: ${getBreakpoints(offsets)}` : ''}
              ${(pushs || []).length > 0 ? `pushs: ${getBreakpoints(pushs)}` : ''}
              ${(orders || []).length > 0 ? `orders: ${getBreakpoints(orders)}` : ''}
            </span>
          </div>`
    )
    .join('');

function getBreakpoints(columns: number[]) {
  let text = ``;
  if (!isNaN(columns[0]) && columns[0] !== 0) text += `(xs:${columns[0]})`;
  if (!isNaN(columns[1]) && columns[1] !== 0) text += `(sm:${columns[1]})`;
  if (!isNaN(columns[2]) && columns[2] !== 0) text += `(md:${columns[2]})`;
  if (!isNaN(columns[3]) && columns[3] !== 0) text += `(lg:${columns[3]})`;
  if (!isNaN(columns[4]) && columns[4] !== 0) text += `(xl:${columns[4]})`;
  if (!isNaN(columns[5]) && columns[5] !== 0) text += `(xxl:${columns[5]})`;
  return text;
}

@Component({
  selector: 'bs2-ds-grid-mock',
  imports: [Bs2DSRowDirective, Bs2DSColumnDirective, Bs2DSOffsetDirective, Bs2DSPushDirective, Bs2DSOrderDirective],
  template: ``,
  standalone: true,
})
class Bs2DSGridMockComponent {}

const meta: Meta<Bs2DSGridMockComponent> = {
  component: Bs2DSGridMockComponent,
  title: 'Directives/Grid',
  parameters: {
    layout: 'centered',
    docs: {
      autodocs: false,
      description: {
        component: `
          Os sistemas de grid são responsáveis por organizar e estruturar grupos de conteúdo na interface. Eles podem ser utilizados tanto para compor painéis administrativos complexos quanto para subdividir conjuntos de informações de forma consistente e responsiva.
          Extremamente versáteis, permitem criar praticamente qualquer layout por meio de variações de colunas, offsets, espaçamentos, alinhamentos e ordenações — oferecendo flexibilidade para adaptar a estrutura a diferentes dispositivos e necessidades do projeto.
        `.trim(),
      },
    },
  },
  decorators: [
    moduleMetadata({
      imports: [
        Bs2DSGridMockComponent,
        Bs2DSRowDirective,
        Bs2DSColumnDirective,
        Bs2DSOffsetDirective,
        Bs2DSPushDirective,
        Bs2DSOrderDirective,
      ],
    }),
    (storyFunc) => ({
      ...storyFunc(),
      styles: [...(storyFunc().styles || []), `:host { display: block; width: 100%; }`],
    }),
  ],
  argTypes: {},
};
export default meta;
type Story = StoryObj<Bs2DSGridMockComponent>;

export const TwelveColumn: Story = {
